export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Direct, non-archived children of an issue — oldest first, ties broken by number. */
export async function listSubIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.parentId, issueId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Every issue in a project, archived or not. A sub-issue tree never crosses a
 * project boundary, so one project-wide read is all `IssueService` needs to
 * build the parent/child map behind its cycle and depth checks.
 */
export async function listIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

/** Live descendants of an issue, at any depth, found by walking down from it. */
export async function listLiveDescendants(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const all = await listIssuesForProject(orgId, projectId);

  const childrenOf = new Map<IssueId, Issue[]>();
  for (const candidate of all) {
    if (candidate.parentId === null) continue;
    const bucket = childrenOf.get(candidate.parentId) ?? [];
    bucket.push(candidate);
    childrenOf.set(candidate.parentId, bucket);
  }

  const result: Issue[] = [];
  const stack = [...(childrenOf.get(issueId) ?? [])];
  while (stack.length > 0) {
    const next = stack.pop();
    if (!next) continue;
    if (next.archivedAt === null) result.push(next);
    stack.push(...(childrenOf.get(next.id) ?? []));
  }
  return result;
}

/** Bulk-archives already-live issues by id; the cascade behind `IssueService.archiveIssue`. */
export async function archiveIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<void> {
  if (issueIds.length === 0) return;

  getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .run();
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */

