    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: descendant.id,
      projectId: descendant.projectId,
    });
  }

  return archived;
}

/**
 * Places, moves or roots an issue. The parent must be a live issue of the
 * same project; the tree may not loop, and the issue's deepest sub-issue may
 * never land past `MAX_SUB_ISSUE_DEPTH` once the move is applied.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    await requireLiveParentInProject(input.orgId, issue.projectId, input.parentId);
  }

  if (issue.parentId === input.parentId) {
    return issue;
  }

  const projectIssues = await issueRepo.listIssuesForProject(
    input.orgId,
    issue.projectId,
  );
  const byId = new Map(projectIssues.map((row) => [row.id, row] as const));
  const childrenOf = buildChildrenMap(projectIssues);

  if (
    input.parentId !== null &&
    isSelfOrDescendant(byId, input.parentId, issue.id)
  ) {
    throw new IssueHierarchyError(issue.id, "cycle");
  }

  const newLevel =
    input.parentId === null ? 0 : levelOf(byId, input.parentId) + 1;
  const heightBelow = subtreeHeight(childrenOf, issue.id);
  if (newLevel + heightBelow > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issue.id, "too_deep");
  }

  const after = await issueRepo.setIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct sub-issues, not archived, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listSubIssues(orgId, issueId);
}

/** Counts over every non-archived issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const descendants = await issueRepo.listLiveDescendants(
    orgId,
    issue.projectId,
    issueId,
  );
  const closed = descendants.filter((descendant) =>
    CLOSED_ISSUE_STATUSES.includes(descendant.status),
  ).length;

  return { total: descendants.length, open: descendants.length - closed, closed };
}

/** The parent given at creation or to `setIssueParent` must be a live issue of the same project. */
async function requireLiveParentInProject(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = requireFound(
    await issueRepo.findIssueById(orgId, parentId),
    "Issue",
    parentId,
  );
  if (parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

function buildChildrenMap(allIssues: readonly Issue[]): Map<IssueId, Issue[]> {
  const map = new Map<IssueId, Issue[]>();
  for (const candidate of allIssues) {
    if (candidate.parentId === null) continue;
    const bucket = map.get(candidate.parentId) ?? [];
    bucket.push(candidate);
    map.set(candidate.parentId, bucket);
  }
  return map;
}

/** True when `candidateId` is `rootId` itself, or sits anywhere below it. */
function isSelfOrDescendant(
  byId: ReadonlyMap<IssueId, Issue>,
  candidateId: IssueId,
  rootId: IssueId,
): boolean {
  let current: IssueId | null = candidateId;
  while (current !== null) {
    if (current === rootId) return true;
    current = byId.get(current)?.parentId ?? null;
  }
  return false;
}

/** A root issue is at level 0; each step down a parent adds one. */
function levelOf(byId: ReadonlyMap<IssueId, Issue>, id: IssueId): number {
  let level = 0;
  let current = byId.get(id)?.parentId ?? null;
  while (current !== null) {
    level += 1;
    current = byId.get(current)?.parentId ?? null;
  }
  return level;
}

/** 0 when `id` has no sub-issues; otherwise one more than its deepest branch. */
function subtreeHeight(
  childrenOf: ReadonlyMap<IssueId, Issue[]>,
  id: IssueId,
): number {
  const children = childrenOf.get(id);
  if (children === undefined || children.length === 0) return 0;
  return (
    1 +
    Math.max(...children.map((child) => subtreeHeight(childrenOf, child.id)))
  );
}

