/**
 * Archiving cascades to every live issue below it, at any depth — leaving a
 * live sub-issue under an archived parent is exactly the drift this prevents.
 * Each cascaded issue gets its own `issue.archived` event so the issues
 * counter, the search index and alerts all react the same way they would to
 * archiving it directly.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const liveDescendants = await issueRepo.listLiveDescendants(
    orgId,
    issue.projectId,
    issueId,
  );

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  if (liveDescendants.length > 0) {
    await issueRepo.archiveIssuesByIds(
      orgId,
      liveDescendants.map((descendant) => descendant.id),
    );
  }

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  for (const descendant of liveDescendants) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: descendant.id,
      projectId: descendant.projectId,
    });
  }

  return archived;
