  });
}

/**
 * When a sub-issue stops being open, its direct parent (only the direct
 * parent — grandparents are untouched) is told once if that leaves it with no
 * open issue below it at any depth. Archived parents and parents without an
 * assignee are silently skipped, as is a parent with no open sub-issues left
 * to begin with (there is nothing to close).
 */
async function notifyParentIfSubIssuesComplete(
  orgId: OrgId,
  issueId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue || issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const remaining = await issueRepo.listLiveDescendants(
    orgId,
    parent.projectId,
    parent.id,
  );
  const stillOpen = remaining.some(
    (descendant) => !CLOSED_ISSUE_STATUSES.includes(descendant.status),
  );
  if (stillOpen) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are done",
    body: `Every sub-issue under "${parent.title}" is now closed`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

