import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { NotFoundError } from "@/server/services/_support";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Notification } from "@/types/notification";
import * as notificationRepo from "@/server/repositories/notification-repository";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissuecheck");
});

afterAll(() => {
  cleanup();
});

describe("sub-issues sanity", () => {
  it("creates a sub-issue and lists/rolls it up", async () => {
    const parent = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Parent" }));
    const child = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id, { title: "Child" }), parentId: parent.id });

    const subs = await issueService.listSubIssues(tenant.actors.member, tenant.org.id, parent.id);
    expect(subs.map(s => s.id)).toEqual([child.id]);

    const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, parent.id);
    expect(rollup).toEqual({ total: 1, open: 1, closed: 0 });
  });

  it("refuses a cycle", async () => {
    const a = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "A" }));
    const b = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id, { title: "B" }), parentId: a.id });

    await expect(
      issueService.setIssueParent(tenant.actors.member, { orgId: tenant.org.id, issueId: a.id, parentId: b.id }),
    ).rejects.toMatchObject({ reason: "cycle" });
  });

  it("refuses too_deep", async () => {
    let prev = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "L0" }));
    for (let i = 1; i <= 3; i++) {
      prev = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id, { title: `L${i}` }), parentId: prev.id });
    }
    // prev is now at level 3 (max). Creating another child directly would be level 4, but per spec depth isn't checked at creation.
    const deepest = await issueService.createIssue(tenant.actors.member, { ...issueInput(tenant.org.id, tenant.project.id, { title: "L4" }), parentId: prev.id });

    // Now try to move deepest's root ancestor under something, forcing recompute... instead directly test setIssueParent too_deep:
    const root = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "NewRoot" }));
    await expect(
      issueService.setIssueParent(tenant.actors.member, { orgId: tenant.org.id, issueId: root.id, parentId: deepest.id }),
    ).rejects.toMatchObject({ reason: "too_deep" });
  });

  it("archive cascades and emits one issue.archived per descendant, with completion notice", async () => {
    const assignee = tenant.userIds.member;
    const parent = await issueService.createIssue(tenant.actors.owner, { ...issueInput(tenant.org.id, tenant.project.id, { title: "CascParent", assigneeId: assignee }) });
    const child = await issueService.createIssue(tenant.actors.owner, { ...issueInput(tenant.org.id, tenant.project.id, { title: "CascChild" }), parentId: parent.id });
    const grandchild = await issueService.createIssue(tenant.actors.owner, { ...issueInput(tenant.org.id, tenant.project.id, { title: "CascGrandchild" }), parentId: child.id });

    const archivedEvents: unknown[] = [];
    const off = subscribe("issue.archived", (p) => { archivedEvents.push(p); });

    try {
      await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, child.id);
      expect(archivedEvents).toHaveLength(2); // child + grandchild
      const childRow = await issueRepo.findIssueById(tenant.org.id, child.id);
      const gcRow = await issueRepo.findIssueById(tenant.org.id, grandchild.id);
      expect(childRow?.archivedAt).not.toBeNull();
      expect(gcRow?.archivedAt).not.toBeNull();

      const parentRow = await issueRepo.findIssueById(tenant.org.id, parent.id);
      expect(parentRow?.archivedAt).toBeNull(); // parent untouched

      const notifs = await notificationRepo.listNotifications({ orgId: tenant.org.id, recipientId: assignee, unreadOnly: false, limit: 25 });
      const completed = notifs.items.filter((n: Notification) => n.kind === "sub_issues_completed");
      expect(completed).toHaveLength(1);
    } finally {
      off();
    }
  });
});
